import { Component, OnInit, AfterViewInit, ViewChild, ElementRef } from '@angular/core';
import { VozackaDozvola, VozackaService } from '../../services/vozacka.service';
import { NgForm } from '@angular/forms';
import { AuthService } from '../../services/auth.service';

declare var bootstrap: any;

@Component({
  selector: 'app-vozacka',
  templateUrl: './vozacka.component.html',
  styleUrls: ['./vozacka.component.css']
})
export class VozackaComponent implements OnInit, AfterViewInit {

  @ViewChild('vozackaModal', { static: false }) vozackaModalRef!: ElementRef;

  vozacke: VozackaDozvola[] = [];
  token: string = '';
  rola: string = '';

  noviZahtev = { grad: '', kategorijeStr: '' };
  modalInstance: any;

  showAlert: boolean = false;
  alertMessage: string = '';
  alertType: 'success' | 'error' = 'success';

  constructor(private vozackaService: VozackaService, private authService: AuthService) { }

  ngOnInit(): void {
    this.token = localStorage.getItem('jwtToken') || '';
    this.rola = this.authService.getRoleFromToken();
    this.ucitajVozacke();
  }

  ngAfterViewInit(): void {
    if (this.vozackaModalRef && this.vozackaModalRef.nativeElement) {
      this.modalInstance = new bootstrap.Modal(this.vozackaModalRef.nativeElement);
    }
  }

  openVozackaModal(): void {
    if (this.modalInstance) this.modalInstance.show();
    else console.error('Modal nije inicijalizovan!');
  }

  podnesiZahtev(form: NgForm): void {
    if (form.invalid) return;

    const kategorije = this.noviZahtev.kategorijeStr.split(',').map(k => k.trim());
    const payload = { grad: this.noviZahtev.grad, kategorije };

    this.vozackaService.podnesiZahtev(payload).subscribe({
      next: res => {
        if (this.modalInstance) this.modalInstance.hide();
        form.resetForm();
        this.ucitajVozacke();
        this.alertType = 'success';
        this.alertMessage = res;
        this.showAlert = true;
      },
      error: err => {
        this.alertType = 'error';
        this.alertMessage = err.error || 'Došlo je do greške pri podnošenju zahteva.';
        this.showAlert = true;
      }
    });
  }

  ucitajVozacke(): void {
    this.vozackaService.dohvatiSve().subscribe({
      next: (res) => this.vozacke = res,
      error: (err) => console.error(err)
    });
  }

  closeAlert(): void {
    this.showAlert = false;
  }

  get imaAktivanZahtev(): boolean {
    return this.vozacke.some(z => z.status === 'CEKANJE' || z.status === 'DOZVOLJEN');
  }

  get isEmployer(): boolean {
    return this.rola === 'EMPLOYER';
  }

  prihvatiZahtev(id: number) {
    this.vozackaService.odobriZahtev(id).subscribe({
      next: res => {
        this.ucitajVozacke();
        this.alertMessage = res?.message || 'Zahtev je odobren!';
        this.alertType = 'success';
        this.showAlert = true;
      },
      error: err => {
        console.error(err);
        this.alertMessage = err.error?.message || 'Došlo je do greške pri odobravanju zahteva.';
        this.alertType = 'error';
        this.showAlert = true;
      }
    });
  }

  odbijZahtev(id: number) {
    this.vozackaService.odbijZahtev(id).subscribe({
      next: res => {
        this.ucitajVozacke();
        this.alertMessage = res?.message || 'Zahtev je odbijen!';
        this.alertType = 'success';
        this.showAlert = true;
      },
      error: err => {
        console.error(err);
        this.alertMessage = err.error?.message || 'Došlo je do greške pri odbijanju zahteva.';
        this.alertType = 'error';
        this.showAlert = true;
      }
    });
  }

  produziVozacku() {
    this.vozackaService.produzi().subscribe({
      next: res => {
        this.ucitajVozacke();
        this.alertType = 'success';
        this.alertMessage = res || 'Vozačka je produžena!';
        this.showAlert = true;
      },
      error: err => {
        this.alertType = 'error';
        this.alertMessage = err.error || 'Došlo je do greške pri produženju vozačke.';
        this.showAlert = true;
      }
    });
  }

  get mozeProduziti(): boolean {
    return this.vozacke.some(z => z.status === 'DOZVOLJEN');
  }
}
<div class="container mt-5">

  <!-- Dugme za podnošenje zahteva za vozačku -->
  <div class="d-flex justify-content-center mb-4">
    <button class="btn btn-primary">Zahtev za vađenje vozačke dozvole</button>
  </div>

  <!-- Tabela vozačkih dozvola -->
  <h3 class="mb-3 text-center">Moje vozačke dozvole</h3>
  <div class="table-responsive">
    <table class="table table-striped table-bordered">
      <thead class="table-dark">
      <tr>
        <th>#</th>
        <th>Ime</th>
        <th>Prezime</th>
        <th>Datum rođenja</th>
        <th>Datum izdavanja</th>
        <th>Važi do</th>
        <th>Grad</th>
        <th>Broj dozvole</th>
        <th>Kategorije</th>
        <th>Status</th>
      </tr>
      </thead>
      <tbody>
      <tr>
        <td>1</td>
        <td>Marko</td>
        <td>Marković</td>
        <td>10.05.1990</td>
        <td>18.09.2025</td>
        <td>18.09.2035</td>
        <td>Beograd</td>
        <td>AB12345</td>
        <td>A, B</td>
        <td>DOZVOLJEN</td>
      </tr>
      <tr>
        <td>2</td>
        <td>Jovana</td>
        <td>Jovanović</td>
        <td>22.03.1992</td>
        <td>01.06.2024</td>
        <td>01.06.2034</td>
        <td>Novi Sad</td>
        <td>CD67890</td>
        <td>B, C</td>
        <td>CEKANJE</td>
      </tr>
      </tbody>
    </table>
  </div>

  <!-- Modal za podnošenje zahteva -->
  <div class="modal fade" id="vozackaModal" tabindex="-1" aria-labelledby="vozackaModalLabel" aria-hidden="true">
    <div class="modal-dialog">
      <div class="modal-content">
        <div class="modal-header">
          <h5 class="modal-title" id="vozackaModalLabel">Podnesi zahtev za vozačku dozvolu</h5>
          <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
        </div>
        <div class="modal-body">
          <form>
            <div class="mb-3">
              <label for="grad" class="form-label">Grad</label>
              <input type="text" class="form-control" id="grad" placeholder="Unesite grad">
            </div>

            <div class="mb-3">
              <label for="kategorije" class="form-label">Kategorije</label>
              <input type="text" class="form-control" id="kategorije" placeholder="Unesite kategorije odvojene zarezom, npr. A,B">
            </div>

            <div class="modal-footer">
              <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Zatvori</button>
              <button type="submit" class="btn btn-primary">Podnesi zahtev</button>
            </div>
          </form>
        </div>
      </div>
    </div>
  </div>

</div>
